+// The Bin — a sidebar of deleted blocks (newest first, so the delete a user is most likely
+// chasing down is right at the top), each restorable individually. A sibling of `.gramaire__doc`
+// on the OPPOSITE side from the outline, so both can be open together without overlapping.
+function BinSidebar() {
+  if (!binOpen.value) return null;
+  const entries = binnedBlocks.value;
+  return (
+    <nav class="gramaire__bin" aria-label="Deleted blocks">
+      {entries.length === 0 ? (
+        <div class="gramaire__bin-empty">The bin is empty.</div>
+      ) : (
+        <>
+          <ul class="gramaire__bin-list">
+            {entries
+              .slice()
+              .reverse()
+              .map((block) => (
+                <li key={block.id} class="gramaire__bin-item">
+                  <span class="gramaire__bin-label">{cellLabel(block)}</span>
+                  <button
+                    type="button"
+                    class="gramaire__bin-restore"
+                    disabled={blocksLocked()}
+                    onClick={() => restoreFromBin(block.id)}
+                  >
+                    Restore
+                  </button>
+                </li>
+              ))}
+          </ul>
+          <button type="button" class="gramaire__bin-clear" onClick={clearBin}>
+            Empty bin
+          </button>
+        </>
+      )}
+    </nav>
+  );
+}
