+/* The Bin — a sidebar of deleted blocks, mirroring `.gramaire__outline` but on the opposite side
+   of `.gramaire__doc` so both can be open together without overlapping. */
+.gramaire__bin {
+  flex: none;
+  width: 200px;
+  position: sticky;
+  top: 0;
+  max-height: 100%;
+  overflow-y: auto;
+  padding: 20px 14px;
+  border-left: 1px solid var(--border);
+}
+.gramaire__bin-empty {
+  font-family: var(--font-mono);
+  font-size: 11.5px;
+  color: var(--fg-faint);
+  font-style: italic;
+}
+.gramaire__bin-list {
+  list-style: none;
+  margin: 0 0 10px;
+  padding: 0;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+}
+.gramaire__bin-item {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 6px;
+  font-family: var(--font-ui);
+  font-size: 13px;
+}
+.gramaire__bin-label {
+  overflow: hidden;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+  color: var(--fg-secondary);
+}
+.gramaire__bin-restore {
+  flex: none;
+  font-family: var(--font-ui);
+  font-size: 11.5px;
+  padding: 3px 8px;
+  border: 1px solid var(--border);
+  border-radius: 5px;
+  background: var(--bg-1);
+  color: var(--fg);
+  cursor: pointer;
+}
+.gramaire__bin-restore:hover {
+  background: var(--bg-2);
+}
+.gramaire__bin-clear {
+  width: 100%;
+  font-family: var(--font-ui);
+  font-size: 12px;
+  padding: 4px 8px;
+  border: none;
+  border-radius: 5px;
+  background: none;
+  color: var(--fg-faint);
+  cursor: pointer;
+  text-align: left;
+}
+.gramaire__bin-clear:hover {
+  color: var(--fg-secondary);
+}
